/*
 * Include-path fallback for ngx_http_lua_common.h's quote-include of
 * "ngx_http_lua_autoconf.h". The real file is generated by lua-nginx-module's
 * config script next to common.h and wins the quote lookup whenever it exists;
 * this stub is only found when NGX_HTTP_LUA_MODULE_DIR points at a checkout
 * that was never configured in place (the OpenResty bundle/ copy, for one).
 * The generated file defines LUA_DEFAULT_PATH / LUA_DEFAULT_CPATH, which this
 * module never reads, so an empty stub is equivalent here.
 */
